class Base {
public:
    void show() { cout << "Base\n"; }        // NOT virtual
};
class Derived : public Base {
public:
    void show() { cout << "Derived\n"; }     // hides Base::show
};
int main() {
    Derived d;
    Base *p = &d;    // base pointer -> derived object (implicit upcast)
    p->show();       // prints "Base": chosen from the pointer type (static binding)
    d.show();        // prints "Derived": chosen from the object type
}

class Shape {
public:
    virtual double area() const { return 0; }  // virtual: run-time dispatch
    virtual ~Shape() {}                        // virtual destructor
};
class Circle : public Shape {
    double r;
public:
    Circle(double r0) : r(r0) {}
    double area() const override { return 3.14159 * r * r; }
};
// class Rect : public Shape is written the same way; area() returns w * h
Shape *s[2] = { new Circle(2.0), new Rect(3.0, 4.0) };
for (int i = 0; i < 2; i++) cout << s[i]->area() << '\n';  // 12.5664 then 12
for (int i = 0; i < 2; i++) delete s[i];   // ~Circle / ~Rect run because ~Shape is virtual

class Base {
public:
    ~Base() { cout << "~Base\n"; }             // NOT virtual
};
class Derived : public Base {
    int *buf;
public:
    Derived() : buf(new int[100]) {}
    ~Derived() { delete[] buf; cout << "~Derived\n"; }
};
int main() {
    Base *p = new Derived;
    delete p;      // prints only "~Base"; buf leaks (undefined behaviour)
}                  // fix: virtual ~Base() {}  -> "~Derived" then "~Base"

class Animal {                        // abstract class
public:
    virtual void speak() const = 0;   // pure virtual: no body required
    virtual ~Animal() {}
};
class Dog : public Animal {
public:
    void speak() const override { cout << "Woof\n"; }
};
int main() {
    // Animal a;          // error: cannot declare variable of abstract type
    Animal *p = new Dog;  // pointer to abstract type is fine
    p->speak();           // Woof
    delete p;
}

#include <iostream>
using namespace std;
struct Base {
    virtual void f() { cout << "Bf "; }
    void g() { cout << "Bg "; f(); }
};
struct Der : Base {
    void f() override { cout << "Df "; }
    void g() { cout << "Dg "; }
};
int main() {
    Der d; Base *p = &d; Base b = d;
    p->g(); p->Base::f(); b.f(); d.g();
}

#include <iostream>
using namespace std;
struct Part { ~Part() { cout << "~Part "; } };
struct Machine {
    Machine() { cout << "M:" << name() << " "; }
    virtual ~Machine() { cout << "~M:" << name() << " "; }
    virtual const char *name() const { return "machine"; }
};
struct Robot : Machine {
    Part arm;
    Robot() { cout << "R:" << name() << " "; }
    ~Robot() { cout << "~R "; }
    const char *name() const override { return "robot"; }
};
int main() { Machine *m = new Robot; delete m; }

