ifstream fin("marks.txt");
if (!fin.is_open()) { cerr << "open failed\n"; return 1; }
int m;
while (fin >> m)             // stops on end of file or on a non-integer token
    cout << m << ' ';
if (fin.eof())  cout << "\nreached end of file\n";
else if (fin.fail()) { cout << "\nbad data\n"; fin.clear(); }   // clear() resets the state
fin.exceptions(ios::failbit | ios::badbit);   // from now on those errors throw ios::failure

ofstream fout("students.txt");
fout << "Ram " << 78 << '\n' << "Sita " << 91 << '\n';
fout.close();
ifstream fin("students.txt");
string name; int marks;
while (fin >> name >> marks)              // formatted extraction, whitespace separated
    cout << name << ": " << marks << '\n';
fin.clear(); fin.seekg(0);                // rewind to read the file again
string line;
while (getline(fin, line)) cout << line << '\n';   // one line at a time

struct Student { char name[20]; int roll; float gpa; };   // plain data: fixed size, no pointers
Student s = {"Ram", 1, 3.6f}, t;
fstream f("stu.dat", ios::in | ios::out | ios::binary | ios::trunc);
f.write(reinterpret_cast<char*>(&s), sizeof(s));         // record 1
s.roll = 2; f.write(reinterpret_cast<char*>(&s), sizeof(s));   // record 2
f.seekg(0);                                               // get pointer back to start
f.read(reinterpret_cast<char*>(&t), sizeof(t));           // read record 1
cout << t.name << ' ' << t.roll << '\n';                  // Ram 1
int n = 2;                                                // update the n-th record
f.seekp((n - 1) * sizeof(Student), ios::beg);
s.gpa = 3.9f; f.write(reinterpret_cast<char*>(&s), sizeof(s));
f.seekg(0, ios::end);
cout << f.tellg() / sizeof(Student) << " records\n";      // 2 records

